import ast, sys, re
for path in sys.argv[1:]:
    src = open(path).read()
    tree = ast.parse(src)
    names = [n.id for n in ast.walk(tree) if isinstance(n, ast.Name)] + [n.attr for n in ast.walk(tree) if isinstance(n, ast.Attribute)]
    used = set(names)
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for a in node.names:
                n = (a.asname or a.name).split('.')[0]
                if n not in used: print(path, 'unused import', n)
        if isinstance(node, (ast.FunctionDef,)):
            args = [a.arg for a in node.args.args + node.args.kwonlyargs]
            body_names = {n.id for n in ast.walk(node) if isinstance(n, ast.Name)}
            for a in args:
                if a not in body_names and a != 'self': print(path, node.name, 'unused param', a, node.lineno)
            assigned = {}
            for n in ast.walk(node):
                if isinstance(n, ast.Name) and isinstance(n.ctx, ast.Store): assigned.setdefault(n.id, n.lineno)
            loads = {n.id for n in ast.walk(node) if isinstance(n, ast.Name) and isinstance(n.ctx, ast.Load)}
            for v, l in assigned.items():
                if v not in loads and v != '_': print(path, node.name, 'unused var', v, l)
    defs = [n.name for n in tree.body if isinstance(n, ast.FunctionDef)]
    for d in defs:
        if len(re.findall(r'\b%s\b' % d, src)) == 1:
            print(path, 'function only defined here (check other files)', d)

